def write_asset(rel_dir, filename, content):
    for base in ['frontend/public', 'backend/apps/deployments/static']:
        d = os.path.join(BASE_DIR, base, rel_dir)
        os.makedirs(d, exist_ok=True)
        p = os.path.join(d, filename)
        with open(p, 'w', encoding='utf-8') as f:
            f.write(content)
        print(f"  [SAVED] {base}/{rel_dir}/{filename}")

def main():
    print("=== 1. WRITING HIGH-CONTRAST / AUTHENTIC SVGS ===")
    # Addons + Templates
    write_asset('logos/addons', 'vault.svg', VAULT_SVG)
    write_asset('logos/templates', 'vault.svg', VAULT_SVG)

    write_asset('logos/addons', 'vitess.svg', VITESS_SVG)
    write_asset('logos/templates', 'vitess.svg', VITESS_SVG)

    write_asset('logos/templates', 'umami.svg', UMAMI_SVG)
    write_asset('logos/templates', 'ollama.svg', OLLAMA_SVG)
    write_asset('logos/templates', 'open-webui.svg', OPEN_WEBUI_SVG)
    write_asset('logos/templates', 'qwen.svg', QWEN_SVG)
    write_asset('logos/templates', 'cohere.svg', COHERE_SVG)

    print("\n=== 2. UPDATING TEMPLATES.JSON TO PREFER SVGS ===")
    fixtures_path = os.path.join(BASE_DIR, 'backend', 'apps', 'deployments', 'fixtures', 'templates.json')
    with open(fixtures_path, 'r', encoding='utf-8-sig') as f:
        templates = json.load(f)

    updates = 0
    for t in templates:
        for key in ['logo_url', 'icon']:
            url = t.get(key) or ''
            if url.endswith('/ollama.png'):
                t[key] = url.replace('/ollama.png', '/ollama.svg')
                updates += 1
            elif url.endswith('/open-webui.png'):
                t[key] = url.replace('/open-webui.png', '/open-webui.svg')
                updates += 1
            elif url.endswith('/qwen.png'):
                t[key] = url.replace('/qwen.png', '/qwen.svg')
                updates += 1
            elif url.endswith('/cohere.png'):
                t[key] = url.replace('/cohere.png', '/cohere.svg')
                updates += 1

    with open(fixtures_path, 'w', encoding='utf-8') as f:
        json.dump(templates, f, indent=4)
    print(f"Updated {updates} template fixtures to reference SVG logos!")

if __name__ == '__main__':
    main()
